{
  "name": "Trivia Duel Master (Memory & State Engine)",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "trivia-duel",
        "responseMode": "responseNode",
        "options": {}
      },
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 1,
      "position": [200, 300]
    },
    {
      "parameters": {
        "jsCode": "const body = $json.body || {};
const currentMsg = (body.message || '').trim();
const history = Array.isArray(body.chatHistory) ? body.chatHistory : [];

const userMessages = history.filter(h => h.role === 'user').map(h => (h.content || '').trim());
const allUserInputs = [...userMessages];
if (allUserInputs.length === 0 || allUserInputs[allUserInputs.length - 1] !== currentMsg) { allUserInputs.push(currentMsg); }
const roundIndex = allUserInputs.length;

const QUESTIONS = [
  { round: 1, topic: 'Sains & Astronomi', question: 'Planet manakah di tata surya kita yang berjuluk \"Planet Merah\"?', correctKeywords: ['mars', 'b.', 'b'], correctDisplay: 'B. Mars', explanation: 'Warna merah Mars disebabkan oleh tingginya konsentrasi besi oksida di permukaannya.', chips: ['A. Venus', 'B. Mars', 'C. Jupiter', 'D. Merkurius'] },
  { round: 2, topic: 'Sejarah & Komputer', question: 'Siapakah matematikawan yang memecahkan kode mesin enkripsi Enigma pada Perang Dunia II?', correctKeywords: ['alan turing', 'turing'], correctDisplay: 'Alan Turing', explanation: 'Alan Turing memimpin tim di Bletchley Park menggunakan mesin Bombe.', chips: ['Alan Turing', 'Charles Babbage', 'Ada Lovelace', 'John von Neumann'] },
  { round: 3, topic: 'Geografi Dunia', question: 'Danau terdalam di dunia yang menampung 20% air tawar permukaan bumi yang tak beku adalah?', correctKeywords: ['baikal', 'danau baikal'], correctDisplay: 'Danau Baikal (Rusia)', explanation: 'Danau Baikal memiliki kedalaman maksimum 1.642 meter.', chips: ['Danau Baikal', 'Danau Toba', 'Danau Victoria', 'Danau Superior'] },
  { round: 4, topic: 'Logika & Sains Modern', question: 'Berapakah kecepatan cahaya dalam ruang hampa udara (dalam aproksimasi km/detik)?', correctKeywords: ['300.000', '300000', '300.000 km/s', '300000 km/s'], correctDisplay: '300.000 km/detik', explanation: 'Cahaya merambat pada konstanta universal c ≈ 300.000 km/s.', chips: ['300.000 km/detik', '150.000 km/detik', '1.000.000 km/detik', '30.000 km/detik'] }
];

let score = 0; let streak = 0; const roundHistory = [];
for (let i = 0; i < allUserInputs.length; i++) {
  if (i >= QUESTIONS.length) break;
  const q = QUESTIONS[i];
  const ans = allUserInputs[i].toLowerCase();
  const isCorrect = q.correctKeywords.some(kw => ans.includes(kw));
  if (isCorrect) { score += 100 + (streak * 25); streak += 1; roundHistory.push({ round: q.round, correct: true, answerGiven: allUserInputs[i] }); }
  else { streak = 0; roundHistory.push({ round: q.round, correct: false, answerGiven: allUserInputs[i] }); }
}

const currentRoundEvaluated = roundHistory[roundHistory.length - 1];
const prevQ = QUESTIONS[Math.min(roundIndex - 1, QUESTIONS.length - 1)];
const memorySnippet = roundHistory.length > 1 ? `\n\n🧠 *Memori Riwayat:* Dari ${roundHistory.length} babak yang telah kamu lewati, kamu menjawab benar **${roundHistory.filter(r => r.correct).length} dari ${roundHistory.length} pertanyaan**.` : '';

if (roundIndex <= QUESTIONS.length) {
  const evalText = currentRoundEvaluated.correct ? `🎉 **TEPAT SEKALI! (+100 Poin + Streak Bonus)**\nKamu memilih: *\"${currentRoundEvaluated.answerGiven}\"*.\nℹ️ *Fakta:* ${prevQ.explanation}` : `❌ **KURANG TEPAT!**\nKamu memilih: *\"${currentRoundEvaluated.answerGiven}\"*. Jawaban yang benar adalah **${prevQ.correctDisplay}**.\nℹ️ *Fakta:* ${prevQ.explanation}`;
  if (roundIndex < QUESTIONS.length) {
    const nextQ = QUESTIONS[roundIndex];
    return { json: { content: `📊 **[Papan Skor: ${score} Poin | Streak: ${streak} | Babak ${roundIndex + 1}/${QUESTIONS.length}]**\n\n${evalText}${memorySnippet}\n\n---\n\n🔥 **Babak ${nextQ.round} (${nextQ.topic}):**\n*\"${nextQ.question}\"*`, chips: nextQ.chips } };
  } else {
    let rankTitle = score >= 450 ? '🏆 Grand Quiz Master (Legenda Trivia)' : score >= 300 ? '🥈 Perak (Trivia Sage)' : '🥉 Perunggu (Smart Challenger)';
    return { json: { content: `📊 **[Papan Skor Akhir: ${score} Poin | Rank: ${rankTitle}]**\n\n${evalText}${memorySnippet}\n\n---\n\n🏁 **DUEL SELESAI!**\nKamu telah menyelesaikan seluruh 4 babak tantangan Trivia Duel Master.\n- **Total Skor Akhir:** ${score} Poin\n- **Akurasi Jawaban:** ${Math.round((roundHistory.filter(r => r.correct).length / QUESTIONS.length) * 100)}%\n- **Gelar Pencapaian:** **${rankTitle}**`, chips: ['🔄 Mainkan Ulang (Rematch)', '🧠 Kuis Sains Lanjutan', '📜 Lihat Papan Peringkat'] } };
  }
} else {
  return { json: { content: '🧠 **Trivia Duel Master siap untuk sesi kuis baru!**\n\nPilih mode permainan yang ingin kamu mainkan:', chips: ['Mulai Kuis Babak 1', 'Mode Sulit (Hardcore)', 'Mode Campuran Acak'] } };
}"
      },
      "name": "State & Memory Engine",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [480, 300]
    },
    {
      "parameters": {
        "respondWith": "json",
        "responseBody": "={{ $json }}",
        "options": {}
      },
      "name": "Respond to Webhook",
      "type": "n8n-nodes-base.respondToWebhook",
      "typeVersion": 1,
      "position": [720, 300]
    }
  ],
  "connections": {
    "Webhook": { "main": [[{ "node": "State & Memory Engine", "type": "main", "index": 0 }]] },
    "State & Memory Engine": { "main": [[{ "node": "Respond to Webhook", "type": "main", "index": 0 }]] }
  }
}
